-- Demo handwritten signature for the demo Intake Tech (0.29.0): receiving samples signs the chain of custody and
-- places the receiver's handwritten signature and title in its Received area. Fictional image. Alex's own account
-- (akiddle) is left without one: a lab administrator records his in Admin > People and groups ("COA signature").
BEGIN;
SET search_path = lims, public;
SELECT set_config('lims.user_id', (SELECT id::text FROM app_user WHERE username = 'akiddle'), true);
SELECT set_config('lims.reason', 'Sandbox demo data', true);
DO $$ DECLARE d uuid; u RECORD; BEGIN
  PERFORM set_config('lims.group_sync', '1', true);
  SELECT id, signature_document_id INTO u FROM app_user WHERE username = 'intake';
  IF u.id IS NOT NULL AND u.signature_document_id IS NULL THEN
    INSERT INTO document_file (file_name, mime_type, size_bytes, sha256, content)
    VALUES ('signature-intake.png', 'image/png', 7424, 'f5326ef354669f5aa6859a2ac7ce68a024f13460c234f4ced838ccff9b847abe', decode('', 'base64'))
    RETURNING id INTO d;
    UPDATE app_user SET signature_document_id = d, title = COALESCE(title, 'Sample Intake Technician'), signature_set_at = clock_timestamp(), signature_set_by = current_app_user() WHERE id = u.id;
  END IF;
END $$;
COMMIT;
